from collections import deque


def countValidStarts(gas, cost):
    n = len(gas)
    P = [0] * (2 * n + 1)
    for j in range(2 * n):
        P[j + 1] = P[j] + gas[j % n] - cost[j % n]
    dq = deque()
    count = 0
    for j in range(1, 2 * n + 1):
        while dq and P[dq[-1]] >= P[j]:
            dq.pop()
        dq.append(j)
        s = j - n
        if 0 <= s < n:
            while dq[0] < s + 1:
                dq.popleft()
            if P[dq[0]] >= P[s]:
                count += 1
    return count
